const WIND_ANGLE_SERIES = [20,25,30,35,40,45,50,60,70,80,90,100,110,120,130,140,150,160,170,180,190,200,210,220,230,240,250,260,270,280,290,300,310,315,320,325,330,335,340];
export function binValueWind(x) {
    let index = WIND_ANGLE_SERIES.findIndex(e => e >= x);
    if (index < 0)
        return WIND_ANGLE_SERIES[WIND_ANGLE_SERIES.length - 1];
    if (index == 0)
        return WIND_ANGLE_SERIES[0];

    index--;
    const nextIndex = index > WIND_ANGLE_SERIES.length - 1 ? 0 : index + 1;
    if (x - WIND_ANGLE_SERIES[index] >= WIND_ANGLE_SERIES[nextIndex] - x) {
        index = nextIndex;
    }
    let result = WIND_ANGLE_SERIES[index];
    if (result == 360) result = 0;
    return result;
}


export function binValueWindSpd(x) {
    let index = WIND_SERIES.findIndex(e => e >= x);
    if (index < 0)
        return WIND_SERIES[WIND_SERIES.length-1];
    if (index == 0)
        return WIND_SERIES[0];
    index--;
    const nextIndex = index > WIND_SERIES.length - 1 ? 0 : index + 1;
    if (x - WIND_SERIES[index] >= WIND_SERIES[nextIndex] - x) {
        index = nextIndex;
    }
    let result = WIND_SERIES[index];
    return result;
}
  



export function average(values) {
    return values.reduce((a, b) => parseFloat(a) + parseFloat(b), 0) / values.length;
}

export function median(values) {
    values.sort((a, b) => parseFloat(a) - parseFloat(b));
    return values[parseInt(values.length/2)];
}

