export function generatePolarTraces(polar) {
    if (polar == null)
        return [{
            type:'scatterpolar',
            mode:"lines+markers",
            theta: [0],
            name:"TWS 2 kn",
            r: [0],
            line: { shape: 'spline', color: getColorForWind(2) }
        }];

    const polarStruct = polar.polarStruct || polar;
    const traces = [];
    for (let twsIdx = 0; twsIdx < polarStruct.tws.length; twsIdx++) {
        const tws = polarStruct.tws[twsIdx];
        const theta = [];
        const r = [];
        for (let twaIdx = 0; twaIdx < polarStruct.twa.length; twaIdx++) {
            const twaRec = polarStruct.twa[twaIdx];
            theta.push(twaRec.twa);
            r.push(twaRec.boatSpeed[twsIdx]);
        }
        traces.push({
            type: "scatterpolar",
            mode: "lines+markers",
            name: `TWS ${tws} kn`,
            theta: theta,
            r: r,
            line: { shape: 'spline', color: getColorForWind(tws) },
            marker: { color: getColorForWind(tws) }
        });
    }
    return traces;
}

export function createPolar(timeFrames, halfPolar) {
    return Polar.createFromTimeframes(timeFrames, halfPolar);
}
  
  export function binValue(x, step, range) {
    if (x < 0 || x > range) return null;
    return parseInt(Math.floor(x / step) * step);
  }

  
  export function getColorForWind(tws) {
    return windColors(tws).hex();
  }


export function createPolarText(polar) {
    const polarStruct = polar.polarStruct || polar;
    return new Polar(polarStruct).serialiseToText();
}

export function loadPolarFromText(polText) {
    return Polar.loadFromText(polText, null, null);
}

const _saveOrigHTML = new Map();
export function saveButtonSpinnerOn(saveButton) {
  _saveOrigHTML.set(saveButton.id, saveButton.innerHTML);
  saveButton.innerHTML =
    '<img src="icons/spinner.webp" alt="Saving..." style="height: 12px; vertical-align: middle;">';
  saveButton.disabled = true;
}

export function saveButtonSpinnerOff(saveButton) {
  saveButton.innerHTML = _saveOrigHTML.get(saveButton.id);
  saveButton.disabled = false;
}
