window.onload = async () => {
  c.hideLoadingSpinner();
  
  // Check for popup blocker
  const testPopup = window.open("", "_blank", "width=1,height=1");
  if (!testPopup || testPopup.closed || typeof testPopup.closed === 'undefined') {
    alert("Please allow popups for this site for google drive login.");
  } else {
    testPopup.close();
  }
  
  const urlParams = new URLSearchParams(window.location.search);
  const fileId = urlParams.get('id');
  const settingsFileId = urlParams.get('sid');
  const infoFileId = urlParams.get('iid');

  if (fileId != undefined) {
    c.dataStore.setSharedFileParams({id: fileId, sid: settingsFileId, iid: infoFileId});
  } else {
    const url = urlParams.get('url');
    if (url != undefined) {
      c.dataStore.setSharedFileParams({url: url, sid: settingsFileId, iid: infoFileId});
    }
  }

  const fileName = urlParams.get('file');

  const postLoadFn = async () => {
    if (!c.dataStore.isSharedFileMode()) {
      await c.dataStore.loadSettingsAsync();
      c.dataStore.ensurePolarLoadedAsync();
      playerModeButtonSettings.disabled = false;
      playerModeButtonPolar.disabled = false;
    }

    mainSettingsPage = new MainSettingsPage(c.dataStore, gd, c, c.dataStore.getSettings());
    mainSettingsPage.init();

    if (fileName) {
      loadFileByName(fileName);
    }
  };
  gd.initGoogleDriveAsync(postLoadFn);
  document.getElementById("g_id_signin").addEventListener("click", () => {
    gd.initGoogleDriveAsync(postLoadFn);
  });

  updateTrackStyle(c._trackStyle);

  if (c.dataStore.isSharedFileMode()) {
    loadSharedFile();
    const controls = document.getElementById('controls-visible');
    controls.style.display = "none";
  }
  
  updateFileControlButtonState(c.dataStore.getRace());
};



