function createColorLegend(style) {
  const legendContainer = document.getElementById("colorLegend");
  const labelFormatter = (v) => v < 10 ? v.toFixed(1) : v.toFixed(0);
  legendContainer.innerHTML = ""; // Clear previous content
  const t = legendContainer.appendChild(document.createElement("div"));
  t.className = 'color-legend-heading'
  t.innerHTML = style.title;
  const values = style.colorDomain;
  for(let i=0; i < values.length; i++) {
    const val = values[i];
    const row = document.createElement("div");
    row.style.display = "flex";
    row.style.alignItems = "center";
    row.style.marginBottom = "4px";
    
    const swatch = document.createElement("div");
    swatch.style.width = "10px";
    swatch.style.backgroundColor = style.colorMap(val).hex();
    swatch.style.marginRight = "5px";
    swatch.style.border = "1px solid #ccc";
    const label = document.createElement("span");
    swatch.style.height = "15px";
    label.textContent = labelFormatter(val);

    row.appendChild(swatch);
    row.appendChild(label);
    legendContainer.appendChild(row);
  };
}

