async function loadFileByName(fileName) {
  c.showLoadingSpinner();
  try {
    mapplayer.stopPlaying();
    const folder = await gd.ensureDataFolderAsync();
    const result = await gd.downloadNamedFileFromDataFolderAsync(folder, fileName);
    if (result) {
      const doc = {id: result.id, name: fileName};
      await c.dataStore.loadFromGDrive(doc, c.setLoadingMessage);
      updateFileControlButtonState(c.raceData());
      startPlayerWithRace(c.raceData());
      document.getElementById("fileNameSelected").textContent = fileName;
    } else {
      alert(`File not found: ${fileName}`);
    }
  } catch (error) {
    console.error('Error loading file:', error);
    alert(`Error loading file: ${error.message}`);
  } finally {
    c.hideLoadingSpinner();
  }
}

function updateFileControlButtonState(raceData) {
  const shareButton = document.getElementById("shareButton");
  console.log("updateFileControlButtonState");
  if (raceData == null || raceData.sail() == null) {
    console.log("disable buttons");
    shareButton.style.display = "none";
    saveAsButton.style.display = "none";
    saveButton.style.display = "none";
    annotateButton.style.display = "none";
    return;
  }
  
  
  if (raceData.sail().fileName) {
    saveAsButton.style.display = "flex";
  } else {
    saveAsButton.style.display = "none";
  }
  
  if (raceData.sail().hasFileId()) {
    saveButton.style.display = "flex";
    annotateButton.style.display = "flex";
    if (!c.dataStore.isSharedFileMode()) {
      shareButton.style.display = "block";
    } else {
      shareButton.style.display = "none";
    }
  } else {
    saveButton.style.display = "none";
    shareButton.style.display = "none";
    annotateButton.style.display = "none";
  }
}

function showShareDialog(link) {
  const shareLinkInput = document.getElementById("shareLinkInput");
  const shareDialog = document.getElementById("shareDialog");
  const shareFeedback = document.getElementById("shareFeedback");
  shareLinkInput.value = link;
  shareFeedback.textContent = "";
  shareFeedback.style.display = "none";
  shareDialog.style.display = "block";
  shareLinkInput.select();
  shareLinkInput.focus();
}

function hideShareDialog() {
  const shareLinkInput = document.getElementById("shareLinkInput");
  const shareDialog = document.getElementById("shareDialog");
  const shareFeedback = document.getElementById("shareFeedback");
  shareDialog.style.display = "none";
  shareLinkInput.value = "";
  shareFeedback.textContent = "";
  shareFeedback.style.display = "none";
}

async function copyLinkToClipboard() {
  const shareLinkInput = document.getElementById("shareLinkInput");
  const shareFeedback = document.getElementById("shareFeedback");
  const link = shareLinkInput.value;
  
  if (!navigator.clipboard || !navigator.clipboard.writeText) {
    shareFeedback.textContent = "Could not copy to clipboard. Please copy the link manually.";
    shareFeedback.style.display = "block";
    return;
  }
  
  try {
    await navigator.clipboard.writeText(link);
    shareFeedback.textContent = "Link copied!";
    shareFeedback.style.display = "block";
  } catch (error) {
    console.error("Failed to copy to clipboard:", error);
    shareFeedback.textContent = "Could not copy to clipboard. Please copy the link manually.";
    shareFeedback.style.display = "block";
  }
}

