document.getElementById('trackEditorButton').addEventListener('click', (e) => {
  if (trackEditor.isActive()) {
    if (trackEditor.hasUnsavedChanges()) {
      const dialog = document.createElement('div');
      dialog.className = 'modal-dialog';
      dialog.style.display = 'flex';

      const backdrop = document.createElement('div');
      backdrop.className = 'modal-backdrop';
      dialog.appendChild(backdrop);

      const content = document.createElement('div');
      content.className = 'modal-content';
      const changeCount = trackEditor._changeLog ? trackEditor._changeLog.length : 0;
      content.innerHTML = `
        <h3>Close Without Saving?</h3>
        <p>You have ${changeCount} unsaved change${changeCount > 1 ? 's' : ''}. Close without saving?</p>
        <div class="modal-buttons">
          <button id="closeEditorOK" class="primary-button">Close</button>
          <button id="closeEditorCancel" class="secondary-button">Cancel</button>
        </div>
      `;
      dialog.appendChild(content);

      document.body.appendChild(dialog);

      document.getElementById('closeEditorOK').addEventListener('click', () => {
        dialog.remove();
        trackEditor.deactivate();
      });

      const cancelHandler = () => {
        dialog.remove();
      };

      document.getElementById('closeEditorCancel').addEventListener('click', cancelHandler);
      backdrop.addEventListener('click', cancelHandler);
    } else {
      trackEditor.deactivate();
    }
  } else {
    trackEditor.activate();
  }
});


