function trimData() {
  const mmsiArray = Array.from(
    document.querySelectorAll(
      'input[type="checkbox"][id^="progressBarShowHide_"]:checked'
    )
  ).map((checkbox) => checkbox.value);
  
  c.raceData().sail().keepTheseAisTracks(mmsiArray);
}



